def find_path(graph, start, goal):

    def heuristic(node, goal):
        return abs(node[0] - goal[0]) + abs(node[1] - goal[1])
    priority_queue = []
    heapq.heappush(priority_queue, (0, start))
    cost_to_reach = {start: 0}
    parent = {start: None}
    while priority_queue:
        current_cost, current_node = heapq.heappop(priority_queue)
        if current_node == goal:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = parent[current_node]
            return path[::-1]
        cost_to_reach[current_node] = current_cost
        for next_node in graph[current_node]:
            tentative_cost = current_cost + 1
            if next_node not in cost_to_reach or tentative_cost < cost_to_reach[next_node]:
                cost_to_reach[next_node] = tentative_cost
                priority = tentative_cost + heuristic(next_node, goal)
                heapq.heappush(priority_queue, (priority, next_node))
                parent[next_node] = current_node
    return None
